  if(h(2)&&v(1)<=3)return make('restart-after-refusal','初めて声をかける時は慎重でも、一度止まった後には別の進め方を考えやすいようです。最初から勢いで押すより、うまくいかなかった点を手掛かりに組み直す進め方が合うかもしれません。',[1,2]);
  if(h(1)&&h(3)&&v(20)<=3)return make('initiative-before-followup','自分から接点を作り、話を前へ進めようとする姿が浮かびます。一方、方向が決まった後の担当や日付は、最後に一つずつそろえると、始めた話を行動までつなげやすくなりそうです。',[1,3,20],true);
  if(h(1)&&h(3)&&v(19)<=3)return make('initiative-before-decision','自分から接点を作り、会話の中でも次の確認へ進もうとする姿が浮かびます。話を続けるだけでなく、今日は何を判断するかを一つそろえると、前へ進める力を商談の区切りにも使えそうです。',[1,3,19],true);
  const second=rank[1];
  if(h(1)&&h(3)&&h(19)&&h(20)&&second[1]>=70&&rank[0][1]-second[1]<=10){const sd=axisDomain[second[0]],lines={listen:h(4)?(h(6)?'事情を聞いて要点を整理しながら':'相手の事情を聞きながら'):h(6)?'話の要点を整理しながら':'相手の言葉の意味を確かめながら',prepare:h(8)?'話す道筋も用意してから':h(7)?'数字や条件を並べてから':'以前役立った進め方を活かしながら',adapt:h(10)&&h(12)?'相手に合わせて説明を言い換えながら':h(11)?'予定外の話にも向き合いながら':h(10)?'相手に合う話し方を選びながら':'伝わる言葉に言い直しながら',relate:h(14)?'話しやすい入口を作りながら':h(13)?'その後の関係も大切にしながら':'相手の考える時間を残しながら',propose:h(17)&&h(18)?'別の案と比べ方を示しながら':h(18)?'候補の違いを整理しながら':h(17)?'別の方法を提案しながら':'課題の見立てを確かめながら'};return make('forward-with-'+sd,'まず動くことだけに偏らず、'+lines[sd]+'次の確認へ進むやり方が合いそうです。着手・会話の進行・締めくくりを、一連の流れとして使おうとする姿が浮かびます。',[...questions.start,...questions[sd]]);}
  if(v(1)===5&&v(2)===5)return make('initiative-and-restart',v(3)===5?'動き出すところから商談の区切りまで、自分で前へ進めようとする姿が浮かびます。うまくいかない時にも別の手を考え、相手との次の接点を探す進め方が合いそうです。':'まず接点を作り、一度止まっても次の手を考えようとする進め方が合いそうです。会話の区切りでは、判断することと次に動くことを具体化しようとする姿も見えます。',[1,2,3,19,20]);
  if(h(2)&&h(20))return make('restart-and-followup','一度で決まらなくても、別の手と次の行動を考えて話を続けようとする姿が浮かびます。最初の勢いだけに頼らず、止まった後の進め方を作るところでも自分らしさを使えそうです。',[1,2,20]);
